private static final String EOL = System.lineSeparator();

/** Holder for objects that are reused across the split tests. */
private static class TestContext {
    final Options opts;
    final HelpFormatter formatter;
    final StringWriter out;

    TestContext(Options opts, HelpFormatter formatter, StringWriter out) {
        this.opts = opts;
        this.formatter = formatter;
        this.out = out;
    }
}

/** Common setup for the original test – creates the options, the formatter with the custom comparator,
 *  and a StringWriter to capture the output. */
private TestContext createTestContext() {
    Options opts = new Options();
    opts.addOption(new Option("a", "first"));
    opts.addOption(new Option("b", "second"));
    opts.addOption(new Option("c", "third"));

    HelpFormatter formatter = new HelpFormatter();
    formatter.setOptionComparator((opt1, opt2) -> opt2.getKey().compareToIgnoreCase(opt1.getKey()));

    StringWriter out = new StringWriter();

    return new TestContext(opts, formatter, out);
}

/** Test that validates the behaviour of the custom comparator used for sorting options. */
@Test
public void testPrintSortedUsage_SortingComparator() {
    Comparator<Option> comparator = (opt1, opt2) -> opt2.getKey().compareToIgnoreCase(opt1.getKey());

    Option optA = new Option("a", "first");
    Option optB = new Option("b", "second");
    Option optC = new Option("c", "third");

    // Comparator should order options in reverse alphabetical order (case‑insensitive)
    assertTrue(comparator.compare(optB, optA) < 0, "b should come before a");
    assertTrue(comparator.compare(optC, optB) < 0, "c should come before b");
    assertTrue(comparator.compare(optA, optC) > 0, "a should come after c");
}

/** Test that verifies the formatted usage string reflects the sorted order of options. */
@Test
public void testPrintSortedUsage_UsageOutput() {
    TestContext ctx = createTestContext();

    ctx.formatter.printUsage(new PrintWriter(ctx.out), 80, "app", ctx.opts);
    String actual = ctx.out.toString();

    assertEquals("usage: app [-c] [-b] [-a]" + EOL, actual);
}

